def run(v):
    import json
    DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
    def words(s):
        out = []
        for ch in str(s):
            if ch.isdigit():
                out.append(DIG[int(ch)])
        return ' '.join(out)
    def digits_only(s):
        out = ''
        for ch in str(s):
            if ch.isdigit():
                out = out + ch
        return out
    def as_list(x):
        if isinstance(x, list):
            return x
        if isinstance(x, str) and x.strip():
            try:
                p = json.loads(x)
                if isinstance(p, list):
                    return p
            except Exception:
                pass
        return None
    def from_flat(prefix):
        items = dict()
        for k in list(v.keys()):
            if isinstance(k, str) and k.startswith(prefix):
                rest = k[len(prefix):].lstrip('.[')
                n = ''
                while rest and rest[0].isdigit():
                    n = n + rest[0]
                    rest = rest[1:]
                rest = rest.lstrip('].')
                if n and rest and '.' not in rest:
                    items.setdefault(int(n), dict())[rest] = v.get(k)
        out = []
        for i in sorted(items):
            out.append(items[i])
        return out
    def is_true(x):
        return str(x).strip().lower() not in ('false', '0', 'no', 'n', '')
    defaults = [('cards_state', 'error'), ('cards_text', ''), ('cards_json', '[]'), ('card_numbers_json', '[]'), ('card_count', '0'), ('selection_question', 'Hangi kartınızın borcunu öğrenmek istersiniz?'), ('sel_index', ''), ('sel_card', ''), ('sel_name', ''), ('sel_l4w', ''), ('email_state', 'error'), ('email_question', ''), ('bal_outcome', 'none'), ('bal_rc', ''), ('send_outcome', 'none'), ('wk_get_outcome', 'none'), ('wk_decide_outcome', 'none'), ('wk_change_outcome', 'none'), ('read_indices', ''), ('reading_text', ''), ('reading_kind', ''), ('followup_text', ''), ('offer_text', ''), ('on_no_other', 'offer'), ('bal_statement_date', ''), ('route', '')]
    for pair in defaults:
        v[pair[0]] = pair[1]
    v['today_iso'] = str(v.get('now') or '')[:10]
    try:
        raw = as_list(v.get('cards_raw'))
        if raw is None:
            raw = from_flat('load_cards_response.data.data.cards')
        lst = []
        for c in raw:
            if isinstance(c, dict) and c.get('cardNumber'):
                n = str(c.get('cardNumber'))
                l4 = str(c.get('cardNumberLast4') or '').strip() or digits_only(n)[-4:]
                lst.append(dict(n=n, p=str(c.get('productName') or '').strip(), l=l4, m=is_true(c.get('isMainCard', True))))
        rc = str(v.get('cards_rc') or v.get('load_cards_response.data.result.returnCode') or '')
        sc = str(v.get('load_cards_status_code') or v.get('load_cards_response.status_code') or '')
        elig = []
        for i in range(len(lst)):
            if lst[i]['m']:
                elig.append(i)
        if elig:
            v['cards_state'] = 'ok'
        elif lst or rc == 'FB_IVR_CHANNEL_102' or sc == '404':
            v['cards_state'] = 'none'
        lines = []
        for i in range(len(lst)):
            c = lst[i]
            masked = ''
            for ch in c['n']:
                if ch.isdigit() or ch == '*':
                    masked = masked + ch
            first6 = masked[:6] if (len(masked) >= 6 and masked[:6].isdigit()) else ''
            last6 = masked[-6:] if (len(masked) >= 6 and masked[-6:].isdigit()) else ''
            t = 'Kart ' + str(i + 1) + ': ad «' + (c['p'] or 'boş') + '»'
            if not c['p'] or len(c['p']) > 30:
                t = t + ' (bu adı okuma; kartı yalnızca son dört hanesiyle tanıt)'
            t = t + ', son dört hane ' + c['l'] + ' (söylenişi: ' + words(c['l']) + ')'
            if not c['m']:
                t = t + ', EK KART: bu işlem için uygun değil'
            twin = False
            for j in range(len(lst)):
                if j != i and lst[j]['p'].lower() == c['p'].lower() and lst[j]['l'] == c['l']:
                    twin = True
            if twin:
                t = t + ', aynı ad ve aynı son dört haneli başka bir kart var; yalnızca eşleştirme için, ASLA söyleme: son altı hane ' + (last6 or 'bilinmiyor') + ', ilk altı hane ' + (first6 or 'bilinmiyor')
            lines.append(t + '.')
        v['cards_text'] = chr(10).join(lines)
        slim = []
        nums = []
        for c in lst:
            slim.append(dict(p=c['p'], l=c['l'], m=c['m']))
            nums.append(c['n'])
        v['cards_json'] = json.dumps(slim, ensure_ascii=False)
        v['card_numbers_json'] = json.dumps(nums)
        v['card_count'] = str(len(elig))
        names = []
        for i in elig:
            p = lst[i]['p']
            if p and len(p) <= 30 and p not in names:
                names.append(p)
        q = 'Hangi kartınızın borcunu öğrenmek istersiniz?'
        if len(names) >= 2:
            q = q + ' Örneğin, ' + names[0] + ' veya ' + names[1] + ' diyebilirsiniz.'
        elif len(names) == 1:
            q = q + ' Örneğin, ' + names[0] + ' diyebilirsiniz.'
        v['selection_question'] = q
        if len(elig) == 1:
            v['sel_index'] = str(elig[0] + 1)
            v['sel_card'] = lst[elig[0]]['n']
    except Exception:
        v['cards_state'] = 'error'
    try:
        em = str(v.get('email_raw') or v.get('load_email_response.data.data.ibanEmail') or '').strip()
        ct = str(v.get('email_comm_type') or v.get('load_email_response.data.data.communicationType') or '').strip().lower()
        erc = str(v.get('email_rc') or v.get('load_email_response.data.result.returnCode') or '')
        if '{' in em:
            em = ''
        if '{' in ct:
            ct = ''
        if '{' in erc:
            erc = ''
        if erc == '1' or (erc == '' and (em or ct)):
            v['email_state'] = 'yes' if (em and '@' in em and ct != 'phone') else 'none'
        v['email_raw'] = em
        if v['email_state'] == 'yes':
            parts = em.split('@')
            local = parts[0]
            dom = parts[1] if len(parts) > 1 else ''
            messy = len(local) > 15 or local.count('.') > 1
            for ch in local:
                if ch.isdigit() or ch in '_-':
                    messy = True
            if messy:
                label = dom.split('.')[0]
                v['email_question'] = 'Ekstrenizi ' + local[:1] + ' ile başlayan ' + (label + ' ' if label else '') + 'adresinize göndermemi ister misiniz?'
            else:
                v['email_question'] = 'Ekstrenizi ' + em + ' adresine göndermemi ister misiniz?'
    except Exception:
        v['email_state'] = 'error'
