def run(v):
    import json
    import datetime
    MONTHS = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
    DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
    AP = chr(39)
    CURS = [('debtTL', 'Türk Lirası', 'kuruş'), ('debtUSD', 'Dolar', 'sent'), ('debtEUR', 'Euro', 'sent'), ('debtGBP', 'İngiliz Sterlini', 'peni')]
    SUF = dict([('Lirası', 'Lirasıdır'), ('kuruş', 'kuruştur'), ('Dolar', 'Dolardır'), ('sent', 'senttir'), ('Euro', 'Eurodur'), ('Sterlini', 'Sterlinidir'), ('peni', 'penidir')])
    Y1 = ['', 'dir', 'dir', 'tür', 'tür', 'tir', 'dır', 'dir', 'dir', 'dur']
    Y10 = ['dir', 'dur', 'dir', 'dur', 'tır', 'dir', 'tır', 'tir', 'dir', 'dır']
    def words(s):
        out = []
        for ch in str(s):
            if ch.isdigit():
                out.append(DIG[int(ch)])
        return ' '.join(out)
    def pdate(s):
        try:
            p = str(s or '').strip().split('.')
            return datetime.date(int(p[2]), int(p[1]), int(p[0]))
        except Exception:
            return None
    def sdate(d):
        return str(d.day) + ' ' + MONTHS[d.month - 1] + ' ' + str(d.year)
    def ysuf(d):
        o = d.year % 10
        t = (d.year // 10) % 10
        return AP + (Y1[o] if o else Y10[t])
    def num(b, k):
        try:
            return float(b.get(k))
        except Exception:
            return 0.0
    def grp(n):
        s = str(n)
        out = ''
        while len(s) > 3:
            out = '.' + s[-3:] + out
            s = s[:-3]
        return s + out
    def amt(x, cur):
        c = int(round(abs(x) * 100))
        t = grp(c // 100) + ' ' + cur[1]
        if c % 100:
            t = t + ' ' + str(c % 100) + ' ' + cur[2]
        return t
    def withdir(t):
        a, sep, b = t.rpartition(' ')
        if not a:
            return t
        return a + ' ' + SUF.get(b, b)
    def as_dict(x):
        if isinstance(x, dict):
            return x
        if isinstance(x, str) and x.strip().startswith('{'):
            try:
                p = json.loads(x)
                if isinstance(p, dict):
                    return p
            except Exception:
                pass
        return None
    def from_flat(prefix):
        out = dict()
        for k in list(v.keys()):
            if isinstance(k, str) and k.startswith(prefix):
                parts = k[len(prefix):].split('.')
                node = out
                for p in parts[:-1]:
                    if not isinstance(node.get(p), dict):
                        node[p] = dict()
                    node = node[p]
                node[parts[-1]] = v.get(k)
        return out
    def join_names(ns):
        if len(ns) == 1:
            return ns[0]
        return ', '.join(ns[:-1]) + ' ve ' + ns[-1]
    lst = json.loads(str(v.get('cards_json') or '[]'))
    nums = json.loads(str(v.get('card_numbers_json') or '[]'))
    a = v.get('cards_balance_args')
    idx = a.get('card_index') if isinstance(a, dict) else None
    if idx in (None, ''):
        idx = v.get('cards_balance_args.card_index')
    tool_path = idx not in (None, '')
    if not tool_path:
        idx = v.get('sel_index')
    bal = as_dict(v.get('bal'))
    if not bal:
        bal = from_flat('cards_balance_response.data.data.' if tool_path else 'fetch_single_response.data.data.')
    rc = str(v.get('bal_rc') or '')
    try:
        i = int(float(str(idx)))
    except Exception:
        i = 0
    if bal and not (1 <= i <= len(lst)):
        for j in range(len(lst)):
            if lst[j].get('m') and lst[j].get('l') == str(bal.get('cardNumberLast4') or ''):
                i = j + 1
                break
    if (not bal) or rc not in ('', '1') or not (1 <= i <= len(lst)) or not ('statementDate' in bal or 'debtTL' in bal):
        v['route'] = 'error'
        return
    card = lst[i - 1]
    name = str(card.get('p') or '')
    if len(name) > 30:
        name = ''
    l4 = str(card.get('l') or bal.get('cardNumberLast4') or '')
    l4w = words(l4)
    intro = 'Sonu ' + l4w + ' ile biten ' + (name + ' ' if name else '') + 'kartınız'
    try:
        today = datetime.date.fromisoformat(str(v.get('now') or '')[:10])
    except Exception:
        today = None
    sd = pdate(bal.get('statementDate'))
    ld = pdate(bal.get('lastPayDate'))
    nsd = pdate(bal.get('nextStatementDate'))
    blocks = []
    for cur in CURS:
        b = as_dict(bal.get(cur[0]))
        if b:
            blocks.append((cur, b))
    tlb = as_dict(bal.get('debtTL')) or dict()
    owing = []
    for cb in blocks:
        if num(cb[1], 'remainingDebt') > 0.004:
            owing.append(cb)
    top = str(bal.get('statementPaymentStatus') or '').upper()
    def totals(lead, none_text):
        pos = []
        clear = []
        for cb in blocks:
            if num(cb[1], 'totalDebt') > 0.004:
                pos.append(amt(num(cb[1], 'totalDebt'), cb[0]))
            else:
                clear.append(cb[0][1])
        if not pos:
            return [none_text]
        out = [lead + join_names(pos) + '.']
        if clear:
            out.append(join_names(clear) + ' borcunuz bulunmamaktadır.')
        return out
    parts = []
    kind = 'debt'
    if sd is None:
        kind = 'no_debt'
        t = intro + 'ın henüz kesilmiş bir ekstresi olmadığı için ekstre borcunuz bulunmamaktadır.'
        if nsd is not None:
            t = t + ' İlk hesap kesim tarihiniz ' + sdate(nsd) + ' olacak.'
        parts.append(t)
    elif today is not None and (today == nsd or today == sd):
        kind = 'total'
        parts.append('Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek.')
        parts.extend(totals(intro + 'ın ekstre sonrası harcamalar dahil toplam borcu: ', intro + 'ın güncel bir borcu bulunmamaktadır.'))
    elif top == 'NO_DEBT' or not owing:
        kind = 'no_debt'
        t = intro + 'ın ' + sdate(sd) + ' tarihli ekstresinden borcunuz bulunmamaktadır.'
        tot = num(tlb, 'totalDebt')
        if tot > 0.004:
            t = t + ' Gelecek dönemler dahil toplam borcunuz ' + withdir(amt(tot, CURS[0])) + '.'
        else:
            t = t + ' Gelecek dönemler dahil bir borcunuz bulunmamaktadır.'
        if ld is not None:
            if today is not None and ld == today:
                t = t + ' Son ödeme tarihiniz bugündür.'
            elif today is not None and ld < today:
                t = t + ' Son ödeme tarihiniz ' + sdate(ld) + ' idi.'
            else:
                t = t + ' Son ödeme tarihiniz ' + sdate(ld) + ' olacaktır.'
        parts.append(t)
    elif today is not None and ld is not None and today > ld:
        parts.append(intro + 'a ait ' + sdate(sd) + ' tarihinde kesilen ekstrenin son ödeme tarihi ' + sdate(ld) + ' idi ve bu tarih geçti.')
        parts.extend(totals('Ekstre sonrası harcamalar dahil güncel toplam borcunuz: ', 'Kartınızın güncel bir borcu bulunmamaktadır.'))
        if str(bal.get('automaticPaymentFlag') or '').upper() == 'Y' and num(tlb, 'remainAutomaticPaymentAmount') > 0.004:
            parts.append('Otomatik ödeme talimatınızdan alınacak kalan tutar ' + withdir(amt(num(tlb, 'remainAutomaticPaymentAmount'), CURS[0])) + '.')
    else:
        first = True
        for cb in owing:
            cur = cb[0]
            b = cb[1]
            x = amt(num(b, 'statementDebt'), cur)
            mp = num(b, 'minPayment')
            rd = num(b, 'remainingDebt')
            rmp = num(b, 'remainingMinPayment')
            if cur[0] == 'debtTL':
                if rmp > 0.004 and rmp >= mp:
                    s = 'Türk Lirası borcunuz ' + x + ', ödenmesi gereken minimum tutar ' + withdir(amt(mp, cur)) + '.'
                elif rmp <= 0.004:
                    s = 'Türk Lirası borcunuz ' + x + ', kalan toplam borcunuz ' + withdir(amt(rd, cur)) + '. Minimum ödemenizi yaptığınız için teşekkür ederiz.'
                else:
                    s = 'Türk Lirası borcunuz ' + x + ', ödenmesi gereken minimum tutar ' + amt(mp, cur) + ', kalan toplam borcunuz ' + amt(rd, cur) + ', kalan minimum ödeme tutarınız ' + withdir(amt(rmp, cur)) + '.'
            else:
                s = cur[1] + ' borcunuz ' + x + ', kalan toplam borcunuz ' + amt(rd, cur) + ', ödenmesi gereken minimum tutar ' + withdir(amt(mp, cur)) + '.'
            if first:
                s = intro + 'a ait ' + sdate(sd) + ' tarihinde kesilen ekstre ' + s
                first = False
            parts.append(s)
        clear = []
        for cb in blocks:
            if num(cb[1], 'remainingDebt') <= 0.004:
                clear.append(cb[0][1])
        if clear:
            parts.append(join_names(clear) + ' borcunuz bulunmamaktadır.')
        if ld is not None:
            if today is not None and ld == today:
                parts.append('Borçlarınız için son ödeme tarihiniz bugündür.')
            else:
                parts.append('Borçlarınız için son ödeme tarihiniz ' + sdate(ld) + ysuf(ld) + '.')
    v['reading_text'] = ' '.join(parts)
    v['reading_kind'] = kind
    v['sel_index'] = str(i)
    v['sel_card'] = str(nums[i - 1]) if i - 1 < len(nums) else ''
    v['sel_name'] = name
    v['sel_l4w'] = l4w
    v['bal_statement_date'] = str(bal.get('statementDate') or '')
    read = []
    for x in str(v.get('read_indices') or '').split(','):
        if x:
            read.append(x)
    if str(i) not in read:
        read.append(str(i))
    v['read_indices'] = ','.join(read)
    others = 0
    for j in range(len(lst)):
        if lst[j].get('m') and str(j + 1) not in read:
            others = others + 1
    estate = str(v.get('email_state') or '')
    if estate == 'yes' and sd is not None:
        offer = 'Hesap kesim tarihinizi değiştirebilirim ya da ekstrenizi kayıtlı mail adresinize gönderebilirim.'
    else:
        offer = 'Hesap kesim tarihinizi değiştirebilirim.'
    v['offer_text'] = offer
    if kind == 'no_debt':
        v['on_no_other'] = 'menu'
    elif estate == 'error':
        v['on_no_other'] = 'email_error'
    else:
        v['on_no_other'] = 'offer'
    v['followup_text'] = ''
    if others > 0:
        v['followup_text'] = 'Başka bir kartınızın borcunu öğrenmek ister misiniz?'
        v['route'] = 'main'
    elif kind == 'no_debt':
        v['route'] = 'end_menu'
    elif estate == 'error':
        v['route'] = 'end_error'
    else:
        v['followup_text'] = offer
        v['route'] = 'main'
vars['route'] = 'error'
try:
    run(vars)
except Exception:
    vars['route'] = 'error'
vars['bal_outcome'] = 'consumed'
vars['bal'] = ''
